const profileStateSchema = z.enum(["signed_out", "login_pending", "signed_in", "recovery_required", "removed"]);
const sessionStateSchema = z.enum(["starting", "active", "idle", "terminal", "recovery_required"]);
const runtimeProfileSourceKindSchema = z.enum(["session_start", "turn_start", "queue_start"]);
const sessionAdoptionLivenessSchema = z.enum(["live", "not_live", "unknown"]);
const sessionAdoptionCandidateStatusSchema = z.enum(["pending", "claiming", "adopted", "fenced"]);
const sessionPersonalRuntimeBindingStateSchema = z.enum(["active", "detaching", "detached"]);
const claudeProcessAuthorityStateSchema = z.enum(["claimed", "bound", "releasing", "released"]);
const claudeProcessRuntimeScopeSchema = z.enum(["managed", "personal"]);
const providerAccountAuthorityKeySchema = z.string()
  .regex(/^v1:(?:codex|claude):[a-f0-9]{64}$/u);
const providerAccountAuthorityKeyMatchesProvider = (
  provider: AdoptableProvider,
  accountKey: string,
): boolean => accountKey.startsWith(`v1:${provider}:`);
const codexProviderAccountAuthorityKeyForEmail = (email: string): string =>
  `v1:codex:${createHash("sha256").update(email.trim().toLowerCase()).digest("hex")}`;
const profileStateAllowsProviderSessionAuthority = (
  provider: Provider,
  state: ProfileRecord["state"],
): boolean => provider === "claude"
  ? state === "signed_in" || state === "signed_out"
  : provider === "codex" && state === "signed_in";
const sessionAdoptionProviderThreadIdSchema = z.string().min(1).max(200);
const sessionAdoptionProviderProjectRootSchema = z.string().min(1).refine(
  // Personal provider homes are supported on Darwin/Linux; keep the runtime
  // boundary aligned with the SQLite leading-slash invariant.
  (value) => value.startsWith("/")
    && isAbsolute(value)
    && utf8Bytes(value) <= 8 * 1_024
    && !containsUnsafeTerminalScalar(value),
  "Provider project root is invalid.",
);
const claudeProcessIdentitySchema = z.object({
  pid: z.number().int().positive().safe(),
  pidDomain: z.enum(["darwin", "linux"]),
  procStart: z.string().min(1).max(128).regex(/^[\x20-\x7e]+$/u),
}).strict();
const claudeProcessAuthorityKeySchema = z.object({
  providerThreadId: sessionAdoptionProviderThreadIdSchema,
  profileId: profileIdSchema,
  runtimeScope: claudeProcessRuntimeScopeSchema,
}).strict();
const providerAuthenticationSchema = z.object({
  profileId: profileIdSchema,
  processGeneration: z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER),
  provider: providerSchema,
  signedIn: z.literal(true),
}).strict();
// Correlated to provider_accounts. The invoking CLI owns this exact
// foreground child across daemon restarts until a durable terminal receipt.
const unsettledForegroundProviderLoginSql = `EXISTS(
  SELECT 1 FROM mutation_attempts mutation
  JOIN mutation_provider_authorities authority ON authority.attempt_id=mutation.id
  WHERE mutation.kind='account.'||provider_accounts.provider||'-login'
    AND mutation.state IN ('prepared','effect_started','ambiguous')
    AND authority.provider_account_id=provider_accounts.id
    AND authority.role='primary'
    AND authority.profile_id=provider_accounts.profile_id
    AND authority.provider=provider_accounts.provider
    AND authority.binding_generation=provider_accounts.binding_generation
    AND authority.process_generation=provider_accounts.process_generation
    AND authority.provenance IN (
      'account_'||provider_accounts.provider||'_login',
      'legacy_account_'||provider_accounts.provider||'_login'
    )
    AND mutation.authority_id=authority.profile_id
    AND mutation.authority_generation=authority.process_generation
    AND (SELECT COUNT(*) FROM mutation_provider_authorities captured
         WHERE captured.attempt_id=mutation.id)=1
    AND NOT EXISTS(SELECT 1 FROM mutation_resolutions resolution WHERE resolution.attempt_id=mutation.id)
)`;
const interactionListPositionSchema = z.object({
  requestedAt: unixMillisecondsSchema,
  publicId: z.string().uuid(),
}).strict();

export type InteractionListPosition = z.infer<typeof interactionListPositionSchema>;

export type InteractionListPage = Readonly<{
  interactions: readonly InteractionRecord[];
  nextPosition: InteractionListPosition | null;
}>;

export const ATTENTION_NOTIFICATION_SNAPSHOT_LIMIT = 64;

export type AttentionNotificationSnapshot =
  | Readonly<{
      interactions: readonly InteractionRecord[];
      observedAt: number;
      status: "complete";
    }>
  | Readonly<{
      interactions: readonly [];
      observedAt: number;
      status: "overflow";
    }>;

export type InteractionPersistenceBoundaryEffect = "known_unsent" | "possibly_sent";

export type InteractionPersistenceBoundaryQuarantine = Readonly<{
  focalInteraction: InteractionRecord;
  profile: ProfileRecord;
  terminalInteractions: readonly InteractionRecord[];
}>;

